"""Original Portuguese study guides and sourced comparisons; never replace confessional originals."""
import hashlib,json,sqlite3
from pathlib import Path
R=Path(__file__).resolve().parents[1];O=R/'assets/content'
wcf=[
('As Escrituras Sagradas','A revelação geral manifesta Deus, mas não fornece o conhecimento salvador de sua vontade. As Escrituras do Antigo e Novo Testamentos são a regra de fé e vida. Sua autoridade procede de Deus; a Igreja reconhece o cânon, não o cria. A certeza plena envolve o testemunho do Espírito, sem dispensar evidências históricas. Interprete cada passagem em seu contexto e à luz das passagens claras.','55:3:16 61:1:21 19:19:1'),
('Deus e a Trindade','Há um só Deus vivo e verdadeiro, infinito e imutável. Pai, Filho e Espírito Santo são pessoas distintas, da mesma substância, poder e eternidade. Não são três deuses nem três fases temporárias de uma pessoa. A doutrina integra a unidade de Deus com os testemunhos bíblicos acerca do Filho e do Espírito.','5:6:4 40:28:19 43:1:1'),
('O decreto eterno','Deus ordena livre e imutavelmente tudo quanto acontece, sem ser autor do pecado, violentar a vontade das criaturas ou anular causas secundárias. Eleição e reprovação não têm relação simétrica com a culpa: a salvação é graça; a condenação é por pecado. A eleição deve produzir humildade e consolo, não curiosidade especulativa.','49:1:4 45:9:18 59:1:13'),
('A criação','Deus criou o mundo e o ser humano, homem e mulher, à sua imagem. A criação depende do Criador e não é parte de sua essência. A leitura confessional deve ser distinguida dos debates intrarreformados sobre idade da terra e interpretação dos dias; não trate esses debates como resolvidos por uma ilustração.','1:1:1 1:1:27 58:11:3'),
('A providência','Deus sustenta e governa criaturas, ações e coisas, ordinariamente por meios e causas secundárias. A providência abrange o pecado sem transformar Deus em seu autor moral. A certeza da soberania não permite concluir, para cada sofrimento, uma culpa específica da pessoa que sofre.','19:103:19 1:50:20 45:8:28'),
('A queda e o pecado','Adão e Eva caíram por desobediência. A corrupção e culpa do pecado alcançam sua descendência conforme a representação pactual. Pecados particulares procedem dessa corrupção. Na regeneração, a corrupção remanescente continua real, embora o cristão já não esteja sob seu domínio.','1:3:6 45:5:12 45:3:23'),
('O pacto de Deus com o homem','A relação entre Deus e o ser humano envolve condescendência divina. O pacto de obras e o pacto da graça devem ser distinguidos. A promessa da graça é cumprida em Cristo e administrada diferentemente sob lei e evangelho. O Antigo Testamento não ensinava uma salvação meritória alternativa.','1:2:17 1:3:15 48:3:16 58:9:15'),
('Cristo, o Mediador','Jesus Cristo é verdadeiro Deus e verdadeiro homem, duas naturezas em uma pessoa. Como profeta, sacerdote e rei, ele revela, redime e governa seu povo. Sua obediência e sacrifício satisfazem a justiça divina. Evite reduzir a encarnação a aparência humana ou dividir Cristo em duas pessoas.','43:1:14 54:2:5 58:7:25'),
('O livre-arbítrio','A vontade humana é livre de coerção externa, mas seu estado moral varia: inocência, queda, graça e glória. O pecador não consegue, por suas forças, converter-se ao bem espiritual que acompanha a salvação. Na graça, a vontade é libertada, embora permaneça a luta contra o pecado.','43:8:34 45:8:7 50:2:13'),
('A vocação eficaz','Deus chama eficazmente os eleitos por sua Palavra e Espírito, renovando mente, coração e vontade. A pessoa vem livremente a Cristo, tornada disposta pela graça. A proclamação externa do evangelho deve ser distinguida dessa obra interna. Não conclua a eleição de alguém a partir de impressões subjetivas.','45:8:30 43:6:44 26:36:26'),
('A justificação','Deus perdoa o pecado e aceita o crente como justo, por causa da justiça de Cristo imputada e recebida pela fé. A fé é instrumento, não mérito. Boas obras não fundamentam esse veredito, mas seguem a fé viva. Justificação e santificação são distintas e inseparáveis na vida cristã.','45:3:28 45:4:5 47:5:21'),
('A adoção','Os justificados são recebidos na família de Deus, com acesso, cuidado, disciplina paterna e herança. Adoção não significa que a essência humana se torna divina. O crente deve reconhecer a graça, a comunhão e a responsabilidade próprias dessa relação.','45:8:15 48:4:5 62:3:1'),
('A santificação','Os unidos a Cristo são santificados pela Palavra e pelo Espírito. A santificação abrange todo o ser, mas permanece incompleta nesta vida. A luta real contra o pecado não anula a regeneração; a graça não dispensa meios de obediência.','52:5:23 45:6:14 43:17:17'),
('A fé salvadora','A fé salvadora é dom do Espírito e se fortalece ordinariamente pela Palavra, sacramentos e oração. Ela recebe a verdade da Escritura e descansa especialmente em Cristo para justificação, santificação e vida eterna. Sua intensidade pode variar; sua suficiência repousa em Cristo.','49:2:8 45:10:17 43:1:12'),
('O arrependimento para a vida','O arrependimento evangélico reconhece o pecado, busca a misericórdia em Cristo e se volta a Deus. Não compra perdão e não se limita a remorso. Pecados conhecidos devem ser tratados particularmente; confissão e reparação a pessoas feridas têm lugar, respeitadas as situações.','44:11:18 47:7:10 19:51:4'),
('As boas obras','Boas obras são as ordenadas por Deus, não invenções elevadas a obrigação divina. São fruto da fé, gratidão, edificação e evidência de vida, sem merecer salvação. Mesmo as melhores obras dependem da graça e permanecem imperfeitas.','49:2:10 59:2:18 42:17:10'),
('A perseverança dos santos','Os verdadeiramente chamados e santificados não caem total e finalmente da graça. A perseverança se funda em Deus, mas não elimina advertências, meios de graça ou quedas graves. Segurança não autoriza vida deliberadamente impenitente.','43:10:28 50:1:6 58:3:14'),
('A certeza da graça','A certeza pode ser alcançada a partir das promessas, das evidências da graça e do testemunho do Espírito. Não é revelação particular obrigatória nem presunção. Pode ser abalada; a fé fraca não deve ser confundida automaticamente com ausência de fé.','62:5:13 45:8:16 61:1:10'),
('A lei de Deus','A lei moral revela a vontade de Deus e permanece regra de vida. Leis cerimoniais foram cumpridas em Cristo; leis judiciais de Israel não vinculam como código nacional, embora sua equidade instrua. Obediência não é fundamento da justificação.','40:5:17 45:3:31 19:119:97'),
('A liberdade cristã','Cristo liberta da culpa e maldição do pecado e concede acesso a Deus. Deus é Senhor da consciência; ordens humanas não devem ser tratadas como condições divinas de salvação ou adoração. A liberdade não serve de pretexto ao pecado ou à destruição da ordem legítima.','48:5:1 51:2:20 60:2:16'),
('O culto e o Dia do Senhor','O culto deve ser regulado pela Palavra, com reverência e sinceridade. A tradição confessional sustenta um dia em sete para o culto e o primeiro dia da semana como Dia do Senhor na nova aliança. Atos 20:7, 1 Coríntios 16:2 e Apocalipse 1:10 integram o argumento, mas suas divergências exegéticas devem ser examinadas.','43:4:24 2:20:8 44:20:7 46:16:2 66:1:10'),
('Juramentos e votos','Juramentos legítimos invocam Deus como testemunha de verdade, com seriedade e sem fraude. Votos devem ser lícitos e não prometer o que é pecado ou impossível. A fidelidade a Deus não depende de fórmulas mágicas ou obrigações que ultrapassem sua Palavra.','5:6:13 40:5:37 21:5:4'),
('O magistrado civil','A autoridade civil deve buscar justiça e paz. Este texto histórico de 1647 contém disposições sobre religião pública distintas de revisões presbiterianas posteriores. Não o apresente automaticamente como redação da IPB atual. Compare a edição histórica e a revisão adotada por sua igreja.','45:13:1 54:2:2 60:2:13'),
('Casamento e divórcio','O casamento é a união de homem e mulher e envolve fidelidade, auxílio e responsabilidade. A interpretação confessional do divórcio distingue causas legítimas de dissolução arbitrária. Aplicações pastorais exigem cuidado, proteção de pessoas e investigação dos fatos.','1:2:24 40:19:6 46:7:15'),
('A Igreja','A Igreja invisível reúne os eleitos; a visível reúne os que professam a verdadeira religião e seus filhos. Cristo é seu único cabeça. Igrejas locais variam em pureza; a Igreja permanece sob a Palavra, sem atribuir infalibilidade a uma denominação.','49:1:22 44:2:39 46:12:13'),
('A comunhão dos santos','Unidos a Cristo, os cristãos compartilham dons, adoração, serviço e auxílio. A comunhão não apaga a distinção entre Criador e criatura nem abole a responsabilidade por bens e deveres. Deve produzir cuidado concreto.','44:2:42 62:3:17 58:10:24'),
('Os sacramentos','Batismo e Ceia são sinais e selos do pacto da graça instituídos por Cristo. Há relação sacramental entre sinal e realidade significada, sem identidade física entre ambos. A eficácia depende do Espírito e da instituição de Cristo, não de poderes pessoais do ministro.','45:4:11 40:28:19 46:11:23'),
('O batismo','O batismo significa ingresso na Igreja visível e aponta à união com Cristo, regeneração e perdão. A posição presbiteriana inclui os filhos de crentes; não afirma que todo batizado é automaticamente regenerado. Batistas confessionais divergem sobre os sujeitos por sua compreensão da nova aliança.','40:28:19 44:2:39 51:2:11 46:7:14'),
('A Ceia do Senhor','A Ceia recorda o sacrifício único de Cristo e nutre espiritualmente os crentes. A perspectiva reformada rejeita a repetição sacrificial e a transformação substancial do pão e vinho, e afirma participação espiritual real pela fé. A posição católica deve ser estudada em seus próprios termos antes da crítica.','46:11:23 46:10:16 58:10:14'),
('A disciplina eclesiástica','Cristo confiou à Igreja uma autoridade ministerial. A disciplina busca restaurar o pecador, proteger a comunidade e honrar Cristo; não autoriza abuso ou punição arbitrária. Procedimentos devem respeitar verdade, testemunhas e oportunidade de resposta.','40:18:15 46:5:5 48:6:1'),
('Sínodos e concílios','Concílios servem à boa ordem, doutrina e governo e permanecem falíveis e subordinados à Escritura. A relação com o magistrado neste original histórico deve ser distinguida das revisões posteriores. Governo presbiteriano não concede autoridade ilimitada a líderes.','44:15:6 44:17:11 60:5:3'),
('Morte e ressurreição','Depois da morte, as almas não deixam de existir; aguardam a ressurreição corporal. A esperança cristã não é apenas continuidade espiritual, mas redenção integral e ressurreição. Não se devem construir calendários exatos a partir dessa afirmação.','42:23:43 46:15:42 53:4:14'),
('O juízo final','Deus estabeleceu o dia em que julgará o mundo por Jesus Cristo. A expectativa promove sobriedade, consolo e serviço. O dia permanece desconhecido; a especulação não deve substituir arrependimento e fidelidade.','44:17:31 47:5:10 40:24:36')]
guides={'WCF':{},'WSC':{},'WLC':{}}
for i,(title,body,refs) in enumerate(wcf,1):guides['WCF'][str(i)]={'title':title,'body':'## Guia de estudo em português\n\n'+body+'\n\nSíntese própria; confira o texto histórico abaixo e a redação adotada por sua igreja.','refs':refs.split()}
